<?php
declare(strict_types=1);$active_module='bookings';require_once __DIR__.'/layout.php';$u=$supplier_user;$q=db()->prepare('SELECT b.*,p.name property_name FROM supplier_bookings b LEFT JOIN properties p ON p.id=b.property_id WHERE b.supplier_id=? ORDER BY b.created_at DESC LIMIT 200');$q->execute([$u['supplier_id']]);$rows=$q->fetchAll();supply_start('Rezervasyonlar',$active_module);?><section class="page-intro"><p>Acente, API ve doğrudan satış kanallarından gelen rezervasyonları tek ekranda takip edin.</p></section><section class="next-module"><h2>Rezervasyon akışı</h2><?php if(!$rows):?><p>Henüz rezervasyon yok. API ve acente kanalları aktif olduğunda yeni kayıtlar burada anlık görünür.</p><?php endif;?><?php foreach($rows as $b):?><p><b><?=htmlspecialchars($b['booking_reference'])?></b> · <?=htmlspecialchars($b['property_name']?:'Ürün')?> · <?=htmlspecialchars($b['check_in']?:'—')?> / <?=htmlspecialchars($b['check_out']?:'—')?> · <?=number_format((float)$b['total_amount'],2)?> <?=htmlspecialchars($b['currency'])?> · <strong><?=htmlspecialchars($b['status'])?></strong></p><?php endforeach;?></section><?php supply_end(); ?>
